        title: "千问提出 QwenGyre：面向超长程智能体任务的在线强化学习框架",
        tencentSummary: [
          "腾讯摘要称，千问团队提出在线强化学习框架 QwenGyre，面向持续数小时、累计处理百万级 token 的超长程智能体任务。",
          "腾讯摘要称，以弹性调度把空闲 GPU 逐步转入训练且不中断任务，以轨迹树和轨迹预算减少分叉执行的重复计算。",
          "腾讯摘要称，Qwen3.8-2.4T 训练 48 步，NL2RepoBench 通过率由 52.48% 升至 58.54%；总耗时由 Async 的 134.55 小时降至 75.42 小时，加速 1.78 倍。",
        ],
        interpretation: "这是千问团队的技术发布文，价值在于把「超长程」定义清楚：一次执行持续数小时、数百轮相互依赖的交互、各轮累计处理百万级 Token（含反复读入的历史）。两个瓶颈都被点明：Colocate 要等所有任务结束才能整体切到训练，Async 的采样与训练各自部署、空闲 GPU 无法随需求调配，长尾等待造成算力浪费；历史压缩、子智能体委派与重试会让一次执行分叉出多条上下文路径，全部展开要反复处理共享前缀，直接拼接又会改变生成时的原始上下文。解法是把执行、GPU 角色与训练样本分开管理：GPU 切成同构 cell，既能采样也能承载完整模型副本，任务逐步结束时把 cell 转入训练，切换时任务不停、工作区与工具状态保留，KV cache 经 RDMA 迁移；样本侧用 Token-in Token-out 记录每次调用的精确 token ID 与行为策略对数概率，按共享前缀组织成轨迹树，只有被选中的路径展开为样本，并用轨迹预算优先保留主智能体及其摘要路径。Partial Scoring 让超时但已产出可检验结果的任务也能参与训练，拿不到有效评估的执行则丢弃。实验在 Qwen3.8-2.4T 上每次 rollout 约 70 万 Token，48 步后 NL2RepoBench 通过率从 52.48% 升至 58.54%，总耗时从 134.55 小时降到 75.42 小时；122B 模型上最多保留 5 条轨迹时训练分数与梯度范数接近全量，每步前向与反向计算时间减少 25.2%。",
        whyItMatters: "长程强化学习的瓶颈已经从算法转到算力调度与样本构造。把跑不完的任务变成可训练信号，是让 Agent 能力上限随任务时长增长的工程前提。",
