        interpretation: "这是 David Senra 播客 10 月 11 日对谈的整理，信息密度集中在产品节奏与组织方式。增长参照系先摆出来：上线 10 天登顶美国 App Store 免费榜，Sensor Tower 估算 22 天下载破 500 万次，同样数字 ChatGPT 用了 56 天。方法层面有三条可复用：原型与量产之间的鸿沟，2 月用一到两周拼出的 Demo 核心骨架（吉祥物、交互形态）已经出现在最终版里，后面七个月做的是稳定性；把目标量化，列出一百多项具体行为与能力并逐项搭评估集，每周评审只盯最差短板；组织极简，核心团队不到 200 人、两百多位研究员直接向首席 AI 官汇报，不做微观管理。战略选择讲得很清楚：2026 年初全行业在代码 Agent 上跟 Anthropic 硬碰，Meta 判断自己的护城河在 35 亿日活用户的日常生活，论证是不由自主要做的事与真正想做的事之间的划分——AGI 消解报销、排期、订票这类琐事，释放出的意愿时间正好落在 Meta 的产品矩阵里。原文也给了反面参照：OpenClaw 的热度见顶后迅速退潮，原因是偶尔惊艳、多数时候崩溃，这被用来说明稳定性才是消费级 Agent 的门槛。访谈细节还包括 Nat Friedman 的 Agent 调安防摄像头监督他喝水、截图驱动的传播判断、信任像背摔一样从微小事务逐步交托，以及与扎克伯格从第一通复盘电话到敲定重组只用了五六周。原文为访谈整理，观点与估值类数字均为受访者与第三方口径。",
