        interpretation: "原文的架构主张是「先有状态，再有渲染」：世界状态由上游（游戏程序、引擎、动画工具）维护，EdenLive 只做状态到画面的接口与生成式渲染器，因此不绑定具体引擎，只要上游能输出参考视频就能接入。技术上参考视频经 DINOv3 初始化的编码器微调后只保留布局与运动，避免灰盒退化或照搬实拍质感——以粗糙图像为输入时，DreamSim 距离从 0.513 降至 0.368。评测是模型侧吞吐：单张 H100 上 5B 在 832×480 达 73.52 FPS、1280×704 达 29.8 FPS，14B 需 8 张 H100 才 26.76 FPS。原文也写了局限：角色离开画面很久再回来，细节可能对不上；灰盒方块对应哪个角色、贴合程度高低目前由模型定。",
        whyItMatters: "实时渲染与离线视频生成的分界在于能否接入交互回路。把状态与渲染解耦后，画面质量可以迭代而不动玩法逻辑，这是游戏与具身数据增强都能复用的结构。",
        evidenceLevel: "full_text",
        checkedAt: "2026-10-21",
