        interpretation: "关联原文（腾讯混元）把方法拆成四步：专家写场景蓝图，按蓝图去真实世界找代码仓库、数据集与网页搭出工作区并保留原目录结构，先给工作区做体检、记下可核对的事实支撑再出题与定标准，最后让智能体完整执行并保存轨迹。数据侧的读数：16665 个环境、40 个专业领域、60 种文件类型，每个任务平均 21.9 条验证标准，每个工作区平均 42.3 个文件、约 279 KB，完成一个任务平均 31.8 步、33.8 次工具调用、约 7.6 万 tokens；文件类型里表格占 53.3%、图像占 18.7%。最有说服力的是真实与合成的对照：同一批蓝图下，真实工作区文件数是合成工作区的 5.4 倍、文件类型是 2.4 倍、平均体积从 21.5 KB 增至 279 KB，合成环境被过度整理，关键信息挤在少数文件里。金融案例也具体：297 个 CSV 分散在 16 个目录，月度与年度数据混排、缺失值以 −99.99 标记、同一因子命名不一致。训练结果上，A3B 的 GDPval 从 45.5 到 73.6、APEX 从 5.0 到 21.3，ALE 通过率 12.4% 对 ClawGym 的 2.9%；27B 版本 GDPval 82.4，高于 397B-A17B 的 79.7，与原文列出的 Claude Opus 4.8 的 89.1、GPT-5.6 Sol 的 90.1 仍有距离。消融里两个结论值得记：轨迹从 1K 增至 16K，ALE 与 WildClaw 分别提高 13.0 和 8.4 分；同量数据下，41 至 60 轮长轨迹优于 20 轮以内短轨迹。混合验证也优于单路信号，ALE 22.11 高于单用语义评分的 15.62 和单用程序化检查的 14.89。行为层面的变化同样具体：模型在 GDPval 中平均访问 6.52 个外部域名，是基座的 5.3 倍；工作区内定向取证占比从 5.9% 升到 16.2%；工具调用失败后的推理长度从 144 字符增至 614 字符。所有指标均为论文自测口径。",
