        interpretation: "关联原文（APPSO）把迁移拆成可执行的步骤。数据侧，先把 Arc 更新到最新版，Mac 走 Settings–Advanced–Export Data，Windows 在 Advanced 区选择 Export Spaces and tabs，会生成按 Space 与 Folder 分组的「Arc Data Export.md」——可读但不是标准书签文件，需要在目标浏览器里重建结构；Arc Notes 通过 Command Bar 输入 Export Arc Notes 统一导出，Easels 只能逐个 Share Via 存为 PNG，Boosts 无法随数据迁移。四条路线各有取舍：Dia 是唯一提供 Arc 专用迁移入口的浏览器，账号数据、扩展与标签可直接导入，Spaces 进入 Profiles、Folders 变成 Tab Groups，并补回了 Pinned Tabs、垂直侧边栏与 Split View；Zen Browser 基于 Firefox，Workspaces 与 Essentials 分别对应 Spaces 与 Favorites，Split View 最多并排四个标签，Glance 对应 Peek，但无法直接读取 Arc 侧边栏，Chromium 专属扩展可能失效；Chrome 今年 4 月已加入垂直标签页与原生 Split View，配 Workona 以 Space 为单位保存 Resouces 与工作现场；Vivaldi 则提供 Workspaces、分屏与 Auto Archive，但原文提到其 Auto Archive 之后无法恢复已归档内容，这一项没有 Arc Archive 的等价物。",
        whyItMatters: "浏览器正在从通用工具变成 AI 入口，产品路线的切换会直接把迁移成本转嫁给用户。对重度用户而言，真正要判断的不是布局像不像，而是「舍不得的那一项功能」在新栈里有没有可替代实现，以及数据导出格式是否可复用。",
