        title: "Reddit r/opensource 全面封杀 AI 项目，Linux 和 Python 被除名",
        tencentSummary: [
          "腾讯摘要称，Reddit 最大开源社区 r/opensource 版主 10 月 24 日发布新规，全面封禁使用 AI、由 AI 生成或服务 AI 的项目。",
          "腾讯摘要称，新规要求项目维护满 1 年、有 3 名以上贡献者，账号注册满 1 年，不会英语者请另寻社区。",
          "腾讯摘要称，Torvalds 10 月 10 日用 Claude Code 写内核补丁，读取吞吐由每秒 1000 万次升至 3300 万次；Linux、Python 等 38 个项目因此被排除，置顶帖一天收超 2000 条抗议。",
        ],
        interpretation: "关联原文（新智元）还原了事件全貌。版主 u/Wolvereness 在 10 月 24 日晚发布置顶公告《你的 Token 一文不值，别再搞 AI 了》，面向近 40 万成员推出五条新规：项目须活跃维护满 1 年、拥有 3 名以上贡献者且已有社区，不得是笔记或 PDF 阅读器等练手项目，同时禁止发帖招募贡献者——这两条规则形成死循环，新项目无法凑够 3 人就无法发帖，想招人又禁止发帖。发帖者 Reddit 账号须注册满 1 年，私信求情者永久封号。公告还点名封杀 MCP，将整个开源 Agent 工具链排除在外。针对非英语母语者，原文写道「如果你不会说英语，请去找别的社区」，借助翻译软件发帖会被当作 AI 垃圾永久除名。科技博主 chasm 在 X 上列出 38 个按新规无法讨论的顶级开源项目，包括 Linux、FreeBSD、Chromium、Firefox、Python、Rust、Go、Git、Docker 等。原文称，10 月 10 日 Torvalds 在官方内核仓库新建 noref-filemap-read-with-llm 分支，提交 8 个补丁，提交记录注明「均在我的指导下由大语言模型编程助手 Claude Code 完成」。这些补丁解决了困扰内核社区两年的页缓存并发锁争用问题，利用 RCU 无锁宽限期延后内存回收，原文称在 4 核 8 线程酷睿 i7 上把 8 线程读取吞吐量从每秒 1000 万次提升到 3300 万次，单次读取内核周期从 2950 个降至 725 个。Linux 内核已正式合入《AI 编程助手规范》与《工具生成内容指南》，核心原则是人类责任制。禁令发布后一天内置顶帖赞数被踩到 0 分，评论区涌入超 2000 条抗议。",
        whyItMatters: "这场冲突的核心不是 AI 代码的质量问题，而是「用了什么工具」与「交出了什么质量」被混为一谈。当 Linux、Git、Python 等基础项目的主线代码库都已合入 AI 辅助补丁时，「纯血开源」的边界已无法用工具血统来划定。社区治理需要在防止 AI 垃圾灌水与保持开放包容之间找到更精细的平衡。",
