          "腾讯摘要称，所有产品经理都提交过代码，约一半能独立做到上线；市场团队的「数字同事」会主动提醒进度、跨团队问清功能细节。",
          "腾讯摘要称，9 月人均 AI 开销超 1 万美元，他称两年后或只需几百美元；团队正从 Human in the loop 转向 Human on the loop。",
