        interpretation: "关联原文（极客公园）对张涛文章做了详细解读。Manus 内部做了统一代码入口 Manus-mono，配一本写给 AI 看的说明书，让 AI 能看到跨仓库全局；原文称 7 人移动端团队同时负责 2 个产品、4 个 App，进度与网页版基本同步。所有产品经理都向 Manus 提交过代码，约一半能独立把需求做到上线，有的 PM 甚至用视频代替需求文档——原文指出这对应 2.0 大幅加强的视频能力。市场团队有一位「数字同事」，运行在云电脑上的 Slack 机器人，会判断消息与自己是否相关、主动提醒项目进度、跨团队问清功能细节，原文称这套规则是 AI 在开发过程中自己设计的。9 月人均 AI 开销超 1 万美元，少数人一个月用掉七八万美元；张涛给出三条理由：买的是时间和注意力、用最好的模型以了解能力边界、内部 Token 消耗数据可帮助产品改进。他判断两年后同样的工作方式可能只需几百美元。原文指出，文章发布时间点微妙：9 月底 Manus 发布 2.0 版本和个人智能体应用 Cue，10 月初母公司蝴蝶效应完成超 5 亿美元融资并在北京开出 17 个岗位。极客公园认为，Manus 走的是「产品先有，再把内部用法写出来当样板间」的路线，文章里几乎每个岗位都被改写：工程师从写代码变成指挥 AI 干活、PM 能把功能写到上线、设计师也开始写代码。",
