          "腾讯摘要称，其上孵化 Spark-ASR-2.0 等三大专用模型，同传 MOS 由 4.4 升至 4.6；已落地讯飞输入法、AI 录音环等，35 克录音环 2 小时录音约 10 秒传至手机。",
