        interpretation: "关联原文整理自他在 AI Engineer NYC 的演讲。他先给出两个数字：代码产出增长 741%，软件发布速度只增长 30%，并指出卡点在审查——一万行 diff 按人能认真检查的速度可能要审一周，现实中没有谁这样审。他用 4 款 AI 代码审查工具检查同一份代码，每款都指出了真实问题，但彼此发现的问题并不相同，因此单一工具说「没问题」不能作为合并依据；他还区分了「测试全绿」与「维护者愿不愿意合」两种问法，后者还涉及代码风格、改动副作用与仓库历史做法。按瓶颈迁移逻辑，他认为审查之后轮到运维、扩容与安全，且这些不会在一年内全部解决。岗位层面，他提出「产品工程师」：去谈需求、写出可执行的规格、看懂 Agent 交出的结果；他提醒过去给新人的明确工单正被交给 Coding Agent，培养路径被抽走，并承认有人就是喜欢写代码、未必愿意转做需求访谈，「接下来十年可能会很难熬」。落地建议是标出影响面大的代码继续人工重点审、把验收方法做出来再交给 Agent、把资深工程师口中的「这样不行」写成规格与评估，并留下一句判断：最后一位审查员是生产环境。",
        whyItMatters: "这组数据把「AI 提升效率」拆成两个不同市场：写代码几乎免费之后，稀缺资源变成可信任的判断与线上稳定性。对团队的直接含义是，把人力从生产环节挪到高风险改动的审查与可自动验证的验收标准上；对新人的含义更严峻，明确工单是过去最常见的训练材料，若全部交出去，资深判断的传承链需要重新设计。演讲中的就业图表本身不能证明招聘变化全部由 AI 造成，这一点也应保留。",
